import { useActionState } from 'react';

// Server Action defined directly in the file
async function submitContact(prevState: any, formData: FormData) {
  'use server';

  const name = formData.get('name');
  const email = formData.get('email');
  const message = formData.get('message');

  // Simple validation
  if (!name || typeof name !== 'string' || name.trim() === '') {
    return { success: false, error: 'Name is required' };
  }
  if (!email || typeof email !== 'string' || email.trim() === '') {
    return { success: false, error: 'Email is required' };
  }
  if (!message || typeof message !== 'string' || message.trim() === '') {
    return { success: false, error: 'Message is required' };
  }

  // Simulate processing (e.g., saving to DB or sending email)
  await new Promise((resolve) => setTimeout(resolve, 500));

  console.log('Form submitted:', { name, email, message });

  return { success: true, message: 'Message sent successfully!' };
}

const initialState = {
  success: false,
  error: '',
  message: '',
};

export default function ContactForm() {
  const [state, action, isPending] = useActionState(submitContact, initialState);

  return (
    <div style={{ maxWidth: '400px', margin: '0 auto', padding: '20px' }}>
      <h2>Contact Us</h2>

      {state.success && (
        <p style={{ color: 'green', marginBottom: '10px' }}>{state.message}</p>
      )}

      {state.error && (
        <p style={{ color: 'red', marginBottom: '10px' }}>{state.error}</p>
      )}

      <form action={action} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        <div>
          <label htmlFor="name" style={{ display: 'block', marginBottom: '5px' }}>Name</label>
          <input
            type="text"
            id="name"
            name="name"
            required
            style={{ width: '100%', padding: '8px', border: '1px solid #ccc', borderRadius: '4px' }}
          />
        </div>

        <div>
          <label htmlFor="email" style={{ display: 'block', marginBottom: '5px' }}>Email</label>
          <input
            type="email"
            id="email"
            name="email"
            required
            style={{ width: '100%', padding: '8px', border: '1px solid #ccc', borderRadius: '4px' }}
          />
        </div>

        <div>
          <label htmlFor="message" style={{ display: 'block', marginBottom: '5px' }}>Message</label>
          <textarea
            id="message"
            name="message"
            required
            rows={4}
            style={{ width: '100%', padding: '8px', border: '1px solid #ccc', borderRadius: '4px' }}
          />
        </div>

        <button
          type="submit"
          disabled={isPending}
          style={{
            padding: '10px',
            backgroundColor: isPending ? '#ccc' : '#0070f3',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: isPending ? 'not-allowed' : 'pointer',
          }}
        >
          {isPending ? 'Sending...' : 'Send Message'}
        </button>
      </form>
    </div>
  );
}

